fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    // Pre-allocate a vector large enough to hold all elements from v1 and v2.
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    // Copy all elements from v1
    result.extend_from_slice(v1.as_slice());
    // Copy all elements from v2
    result.extend_from_slice(v2.as_slice());
    result
}

